/// What `main` sets up before the window opens, minus the menu bar and the
/// panic log, which the test platform has no use for.
fn launch(cx: &mut TestAppContext) -> (Entity<Workspace>, &mut VisualTestContext) {
    launch_with(cx, Vec::new())
}

/// `launch` with these plugins discovered.
fn launch_with<'a>(
    cx: &'a mut TestAppContext,
    plugins: Vec<&'static crate::db::Plugin>,
) -> (Entity<Workspace>, &'a mut VisualTestContext) {
    cx.update(|cx| {
        cx.text_system()
            .add_fonts(
                guic_gpui_assets::BUNDLED_FONTS
                    .iter()
                    .map(|font| Cow::Borrowed(*font))
                    .collect(),
            )
            .expect("bundled fonts must be loadable");
        gpui_component::init(cx);
        cx.set_global(Fonts::default());
        theme::user::reload();
        let theme = theme::starting_theme(theme::Appearance::of_system(cx.window_appearance()));
        theme.apply_to_components(cx);
        cx.set_global(theme);
        let overrides = store::peek_profiles(&plugins)
            .and_then(|list| list.settings)
            .and_then(|settings| settings.custom_keybindings)
            .unwrap_or_default();
        cx.bind_keys(keybindings::build_bindings(&overrides));
    });
    let mut workspace = None;
    let (_, cx) = cx.add_window_view(|window, cx| {
        let entity = cx.new(|cx| Workspace::new(plugins, window, cx));
        workspace = Some(entity.clone());
        Root::new(entity, window, cx)
    });
    let workspace = workspace.expect("the window builds the workspace");
    // The runner's own `PG*` variables reach `Workspace::new`: GitHub's Windows
    // image sets `PGUSER` and `PGPASSWORD` alone, which opens the connection
    // form over everything a test puts in front. Every test starts from
    // `profiles.toml` only. Settled only when a form was closed, so a launch
    // with none still hands the test the window before its first frame.
    let closed = workspace.update(cx, |workspace, cx| {
        let open = workspace.form.is_some();
        if open {
            workspace.close_form(cx);
        }
        open
    });
    if closed {
        settle(cx);
    }
    (workspace, cx)
}

/// Every write `Workspace` makes on the way out -- buffers on release,
/// profiles on quit -- has to land while `with_home` still points the store at
/// the temporary home, not after the test returns and `HOME` is the real one.
fn quit(workspace: Entity<Workspace>, cx: &mut VisualTestContext) {
    drop(workspace);
    // On the app rather than the window: shutting down removes the window.
    cx.cx.update(|cx| cx.shutdown());
    cx.cx.run_until_parked();
}

/// The app launched on one saved SQLite profile, an empty database, with its
/// query tab in front.
fn launch_on_sqlite(cx: &mut TestAppContext) -> (Entity<Workspace>, &mut VisualTestContext) {
    launch_on_sqlite_holding(cx, "")
}

/// `launch_on_sqlite` over a database `schema` has been run against first.
fn launch_on_sqlite_holding<'a>(
    cx: &'a mut TestAppContext,
    schema: &str,
) -> (Entity<Workspace>, &'a mut VisualTestContext) {
    let directory = store::dbdelve_directory().expect("the test home has a data directory");
    std::fs::create_dir_all(&directory).expect("the data directory must be creatable");
    // An empty file is an empty database. dbdelve opens a SQLite file
    // rather than creating one, so it has to be there first.
    let database = directory.join("e2e.db");
    std::fs::write(&database, b"").expect("the database file must be creatable");
    rusqlite::Connection::open(&database)
        .and_then(|connection| connection.execute_batch(schema))
        .expect("the schema must apply");
    std::fs::write(
        directory.join("profiles.toml"),
        format!(
            "active = \"e2e\"\n\
             [settings]\n\
             check_for_updates = false\n\
             [[profiles]]\n\
             id = \"e2e\"\n\
             name = \"E2E\"\n\
             host = \"\"\n\
             database = \"\"\n\
             user = \"\"\n\
             engine = \"sqlite\"\n\
             path = {:?}\n",
            database.display().to_string()
        ),
    )
    .expect("profiles.toml must be writable");

    let (workspace, cx) = launch(cx);
    front_saved_sqlite(&workspace, cx);
    (workspace, cx)
}

/// The saved SQLite profile in front. CI's live-test job sets `PG*`, which
/// puts an environment profile in front of the saved one on every launch.
fn front_saved_sqlite(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) {
    workspace.update(cx, |workspace, cx| {
        let index = workspace
            .profiles
            .iter()
            .position(|profile| profile.config.engine() == Engine::Sqlite)
            .expect("the saved SQLite profile is restored");
        workspace.activate(index, cx);
    });
    cx.run_until_parked();
}

/// The app launched on `profiles`, the `[[profiles]]` tables of a hand-written
/// `profiles.toml`, with `settings` among the `[settings]` keys, over the SQLite
/// file `DB_PATH` names, `schema` having been run against it first, as
/// `launch_on_sqlite_holding` does for its one profile: every profile that says
/// `DB_PATH` lists the same tables.
fn launch_connections<'a>(
    cx: &'a mut TestAppContext,
    schema: &str,
    settings: &str,
    profiles: &str,
) -> (Entity<Workspace>, &'a mut VisualTestContext) {
    let directory = store::dbdelve_directory().expect("the test home has a data directory");
    std::fs::create_dir_all(&directory).expect("the data directory must be creatable");
    let database = directory.join("e2e.db");
    std::fs::write(&database, b"").expect("the database file must be creatable");
    rusqlite::Connection::open(&database)
        .and_then(|connection| connection.execute_batch(schema))
        .expect("the schema must apply");
    // The first profile is put in front, as a launch that left it there does;
    // a file with no `active` starts on the welcome surface instead.
    let active = profiles
        .lines()
        .find_map(|line| line.strip_prefix("id = "))
        .map(|id| format!("active = {id}\n"))
        .unwrap_or_default();
    std::fs::write(
        directory.join("profiles.toml"),
        format!("{active}[settings]\ncheck_for_updates = false\n{settings}\n{profiles}")
            .replace("DB_PATH", &format!("{:?}", database.display().to_string())),
    )
    .expect("profiles.toml must be writable");
    launch(cx)
}

/// One SQLite profile as `profiles.toml` spells it. `extra` is more scalar
/// keys, which have to come before any table.
fn sqlite_profile(id: &str, name: &str, extra: &str) -> String {
    format!(
        "[[profiles]]\nid = {id:?}\nname = {name:?}\nhost = \"\"\ndatabase = \"\"\n\
         user = \"\"\nengine = \"sqlite\"\npath = DB_PATH\n{extra}\n"
    )
}

/// Opens `main.<table>` of the profile in front as a relation tab, brings it
/// forward and settles; the tab's id.
fn open_own_table(workspace: &Entity<Workspace>, cx: &mut VisualTestContext, table: &str) -> u64 {
    let id = workspace.update_in(cx, |workspace, window, cx| {
        let opened = crate::session::OpenedObject::Relation {
            schema: "main".into(),
            name: table.into(),
            kind: Default::default(),
            filter: String::new(),
            filters: Vec::new(),
        };
        let id = workspace
            .open_object(opened, None, window, cx)
            .expect("the relation opens");
        workspace.activate_tab(Tab::Object(id), window, cx);
        id
    });
    settle(cx);
    id
}

/// The grid of relation tab `id` of the profile in front.
fn relation_grid(
    workspace: &Entity<Workspace>,
    cx: &mut VisualTestContext,
    id: u64,
) -> Entity<gpui_component::table::TableState<crate::result_grid::ResultGrid>> {
    workspace.read_with(cx, |workspace, _| {
        let tab = workspace
            .profile()
            .and_then(|profile| profile.session.objects.iter().find(|tab| tab.id == id))
            .expect("the relation tab is open");
        let ObjectBody::Relation { results, .. } = &tab.body else {
            panic!("the tab is a relation");
        };
        results.clone()
    })
}

/// The first cell `sql` reads from `e2e.db` on a connection of its own, so a
/// test sees what is committed and not what the window's session holds.
fn on_disk(sql: &str) -> Option<String> {
    use rusqlite::types::Value;
    let path = store::dbdelve_directory()
        .expect("the test home has a data directory")
        .join("e2e.db");
    let connection = rusqlite::Connection::open(path).expect("the database opens");
    match connection.query_row(sql, [], |row| row.get::<_, Value>(0)) {
        Ok(Value::Text(text)) => Some(text),
        Ok(Value::Integer(number)) => Some(number.to_string()),
        Ok(_) | Err(_) => None,
    }
}

/// The state of the tab in front, whichever kind it is.
fn front_state(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> QueryState {
    workspace.read_with(cx, |workspace, _| {
        workspace
            .profile()
            .and_then(|profile| profile.session.active_query())
            .cloned()
            .expect("a tab is in front")
    })
}

/// The review in the session, as `(title, carries the draft, error)`.
fn front_review(
    workspace: &Entity<Workspace>,
    cx: &mut VisualTestContext,
) -> Option<(&'static str, bool, Option<String>)> {
    workspace.read_with(cx, |workspace, _| {
        let review = workspace.profile()?.session.apply_review.as_ref()?;
        Some((review.title, review.edits, review.error.clone()))
    })
}

const BIRDS: &str = "create table birds (id integer primary key, name text not null); \
                     insert into birds values (1, 'wren'), (2, 'tit');";

/// Extra keys of a profile an agent may see and may write through, once a
/// person approves.
const VISIBLE_RW: &str = "agent_visible = true\nmode = \"read-write\"";

fn agent_visible(workspace: &Entity<Workspace>, cx: &mut VisualTestContext, id: &str) -> bool {
    workspace.read_with(cx, |workspace, _| {
        workspace
            .profiles
            .iter()
            .find(|profile| profile.id == id)
            .expect("the profile was restored")
            .agent_visible
    })
}

fn saved_visible(id: &str) -> bool {
    store::peek_profiles(&[])
        .expect("profiles.toml reads back")
        .profiles
        .iter()
        .find(|profile| profile.id == id)
        .expect("the profile was saved")
        .agent_visible
}

/// The test platform has no frame loop: what the app leaves for the next
/// frame, such as a dialog handing back the keyboard, waits for this.
fn settle(cx: &mut VisualTestContext) {
    cx.run_until_parked();
    cx.update(|window, cx| window.simulate_next_frame(cx));
    cx.run_until_parked();
}

fn query_tab<T>(
    workspace: &Entity<Workspace>,
    cx: &mut VisualTestContext,
    read: impl FnOnce(&QueryTab, &Window, &App) -> T,
) -> T {
    cx.update(|window, cx| {
        let tab = workspace
            .read(cx)
            .profile()
            .and_then(|profile| profile.session.active_query_tab())
            .expect("a fresh profile opens on a query tab");
        read(tab, window, cx)
    })
}

fn buffer(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> String {
    query_tab(workspace, cx, |tab, _, cx| {
        tab.editor.read(cx).value().to_string()
    })
}

fn editor_has_keyboard(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> bool {
    query_tab(workspace, cx, |tab, window, cx| {
        tab.editor.focus_handle(cx).is_focused(window)
    })
}

fn grid_has_keyboard(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> bool {
    query_tab(workspace, cx, |tab, window, cx| {
        tab.results.focus_handle(cx).is_focused(window)
    })
}

fn sidebar_has_keyboard(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> bool {
    cx.update(|window, cx| {
        workspace
            .read(cx)
            .explorer_focus
            .contains_focused(window, cx)
    })
}

fn dialog_has_keyboard(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> bool {
    cx.update(|window, cx| workspace.read(cx).dialog_focus.is_focused(window))
}

fn ringed_button(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> usize {
    workspace.read_with(cx, |workspace, _| workspace.dialog_choice.get())
}

/// `selec` is no statement `sql::classify` can read, so running it puts up the
/// run-once prompt instead of reaching the database.
fn raise_run_once_prompt(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) {
    cx.simulate_keystrokes("secondary-enter");
    settle(cx);
    workspace.read_with(cx, |workspace, _| {
        assert_eq!(workspace.dialog_in_front.get(), Some("pending-run"));
    });
}

fn assert_startup_theme(
    cx: &mut TestAppContext,
    settings: &str,
    matching: bool,
    expected_theme: impl FnOnce(theme::Appearance) -> &'static str,
) {
    store::tests::with_home(|| {
        let directory = store::dbdelve_directory().unwrap();
        std::fs::create_dir_all(&directory).unwrap();
        std::fs::write(
            directory.join("profiles.toml"),
            format!("[settings]\ncheck_for_updates = false\n{settings}"),
        )
        .unwrap();

        let (workspace, cx) = launch(cx);
        cx.update(|window, cx| {
            let system = theme::Appearance::of_system(window.appearance());
            assert_eq!(
                workspace.read(cx).settings.match_system_appearance,
                matching
            );
            assert_eq!(theme::theme(cx).name, expected_theme(system));
        });
        quit(workspace, cx);
    });
}

#[gpui::test]
fn startup_follows_system_appearance_without_a_saved_choice(cx: &mut TestAppContext) {
    assert_startup_theme(cx, "", true, |system| theme::starting_theme(system).name);
}

#[gpui::test]
fn startup_preserves_a_legacy_fixed_theme(cx: &mut TestAppContext) {
    assert_startup_theme(cx, "theme = \"Dracula\"\n", false, |_| "Dracula");
}

#[gpui::test]
fn startup_preserves_a_saved_system_appearance_opt_out(cx: &mut TestAppContext) {
    assert_startup_theme(
        cx,
        "theme = \"Dracula\"\nmatch_system_appearance = false\n",
        false,
        |_| "Dracula",
    );
}

#[gpui::test]
fn startup_honors_a_saved_system_appearance_opt_in(cx: &mut TestAppContext) {
    assert_startup_theme(
        cx,
        "theme = \"GitHub Dark\"\nmatch_system_appearance = true\n\
         light_theme = \"GitHub Light\"\ndark_theme = \"Dracula\"\n",
        true,
        |system| match system {
            theme::Appearance::Light => "GitHub Light",
            theme::Appearance::Dark => "Dracula",
        },
    );
}

/// A theme file in the test home's theme directory, written whole.
fn write_user_theme(file: &str, name: &str, appearance: &str, surface: &str) {
    let path = store::dbdelve_directory()
        .unwrap()
        .join("themes")
        .join(file);
    let text = format!(
        r##"{{ "name": "{name}", "appearance": "{appearance}", "colors": {{ "surface": "{surface}" }} }}"##
    );
    store::write_file(&path, &text).unwrap();
}

/// One tick of `Workspace::reload_themes` on the test clock, and what it left
/// on screen.
fn poll_themes(cx: &mut VisualTestContext) -> theme::Theme {
    cx.executor().advance_clock(super::THEME_RECHECK);
    settle(cx);
    cx.update(|_, cx| *theme::theme(cx))
}

#[gpui::test]
fn a_rewritten_user_theme_is_worn_again_without_a_restart(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        let directory = store::dbdelve_directory().unwrap();
        let file = directory.join("themes").join("mine.json");
        write_user_theme("mine.json", "Rewritten", "dark", "#102030");
        std::fs::write(
            directory.join("profiles.toml"),
            "[settings]\ncheck_for_updates = false\ntheme = \"Rewritten\"\nopacity = 0.8\n\n\
             [settings.theme_opacity]\nRewritten = 0.6\n",
        )
        .unwrap();

        let (workspace, cx) = launch(cx);
        settle(cx);
        let profiles = || std::fs::read(directory.join("profiles.toml")).unwrap();
        let saved = profiles();
        let before = cx.update(|_, cx| *theme::theme(cx));
        write_user_theme("mine.json", "Rewritten", "dark", "#405060");
        let after = poll_themes(cx);
        std::fs::write(&file, r#"{ "name": "Rewri"#).unwrap();
        let broken = poll_themes(cx);
        write_user_theme("mine.json", "REWRITTEN", "dark", "#708090");
        let recased = poll_themes(cx);
        // A list left without picking puts the theme back at the opacity
        // saved under its old spelling.
        workspace.update_in(cx, |workspace, window, cx| {
            workspace.select_theme(&crate::actions::SelectTheme, window, cx)
        });
        settle(cx);
        cx.simulate_keystrokes("escape");
        settle(cx);
        let restored = cx.update(|_, cx| *theme::theme(cx));
        std::fs::remove_file(&file).unwrap();
        let removed = poll_themes(cx);
        let unsaved = workspace.read_with(cx, |workspace, _| workspace.profiles_unsaved);
        let untouched = profiles() == saved;

        // Closed, the window's loop goes with it: a write after reads nothing.
        let released = workspace.downgrade();
        quit(workspace, cx);
        let revision = theme::user::revision();
        write_user_theme("mine.json", "Rewritten", "dark", "#a0b0c0");
        cx.executor().advance_clock(super::THEME_RECHECK * 3);
        cx.run_until_parked();

        assert_eq!(before.name, "Rewritten");
        assert_eq!(before.surface.hex(), "#102030");
        assert_eq!(after.surface.hex(), "#405060");
        assert_eq!(
            broken, after,
            "a file part way through a write keeps its theme"
        );
        assert_eq!(
            recased.name, "REWRITTEN",
            "a case-only rename is the same theme"
        );
        assert_eq!(recased.surface.hex(), "#708090");
        assert_eq!(removed, recased, "a removed file leaves its theme on");
        assert_eq!(restored, recased);
        for theme in [after, broken, recased, restored, removed] {
            assert_eq!(theme.opacity, before.opacity);
        }
        assert!((before.opacity - 0.6).abs() < f32::EPSILON);
        assert!(!unsaved && untouched, "a reload saves nothing");
        assert!(released.upgrade().is_none());
        assert_eq!(
            theme::user::revision(),
            revision,
            "a closed window polls no more"
        );
    });
}

#[gpui::test]
fn a_theme_renamed_only_in_case_starts_at_its_saved_opacity(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        write_user_theme("mine.json", "REWRITTEN", "dark", "#102030");
        std::fs::write(
            store::dbdelve_directory().unwrap().join("profiles.toml"),
            "[settings]\ncheck_for_updates = false\ntheme = \"Rewritten\"\nopacity = 0.8\n\n\
             [settings.theme_opacity]\nRewritten = 0.6\n",
        )
        .unwrap();
        let (workspace, cx) = launch(cx);
        settle(cx);
        let shown = cx.update(|_, cx| *theme::theme(cx));
        quit(workspace, cx);

        assert_eq!(shown.name, "REWRITTEN");
        assert!((shown.opacity - 0.6).abs() < f32::EPSILON);
    });
}

#[gpui::test]
fn a_listed_theme_that_changes_side_is_neither_previewed_nor_filed_there(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        write_user_theme("mine.json", "Quokka", "dark", "#102030");
        write_user_theme("other.json", "Zircon", "dark", "#111111");
        std::fs::write(
            store::dbdelve_directory().unwrap().join("profiles.toml"),
            "[settings]\ncheck_for_updates = false\ntheme = \"Quokka\"\n",
        )
        .unwrap();
        let (workspace, cx) = launch(cx);
        settle(cx);
        let shown = |cx: &mut VisualTestContext| cx.update(|_, cx| *theme::theme(cx));
        let slots = |cx: &mut VisualTestContext| {
            workspace.read_with(cx, |workspace, _| {
                [theme::Appearance::Dark, theme::Appearance::Light]
                    .map(|side| workspace.settings.theme_for(side).to_string())
            })
        };
        let before = shown(cx);
        let saved = slots(cx);

        workspace.update_in(cx, |workspace, window, cx| {
            workspace.open_palette(
                PaletteMode::Theme(Some(theme::Appearance::Dark)),
                window,
                cx,
            )
        });
        settle(cx);
        cx.simulate_input("zircon");
        settle(cx);
        let dark = shown(cx);
        write_user_theme("other.json", "Zircon", "light", "#eeeeee");
        let light = poll_themes(cx);
        cx.simulate_keystrokes("enter");
        settle(cx);
        let after = shown(cx);
        let kept = slots(cx);
        quit(workspace, cx);

        assert_eq!(dark.name, "Zircon");
        assert_eq!(
            light, before,
            "a light theme is not previewed as a dark one"
        );
        assert_eq!(after, before);
        assert_eq!(kept, saved);
    });
}

#[gpui::test]
fn an_import_and_an_open_theme_list_both_wear_the_theme_as_last_written(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        let directory = store::dbdelve_directory().unwrap();
        write_user_theme("mine.json", "Quokka", "dark", "#102030");
        write_user_theme("other.json", "Zircon", "dark", "#111111");
        std::fs::write(
            directory.join("profiles.toml"),
            "[settings]\ncheck_for_updates = false\ntheme = \"Quokka\"\n",
        )
        .unwrap();
        let (workspace, cx) = launch(cx);
        settle(cx);
        let shown = |cx: &mut VisualTestContext| cx.update(|_, cx| *theme::theme(cx));

        // An import rereads on its own, here for the side the system is not
        // on, while the theme on screen is rewritten: the change that reread
        // took first is worn all the same.
        let system = cx.update(|window, _| theme::Appearance::of_system(window.appearance()));
        workspace.update(cx, |workspace, _| {
            workspace.settings.match_system_appearance = true;
            workspace.settings.set_theme_for(system, "Quokka");
        });
        let away = match system {
            theme::Appearance::Light => theme::Appearance::Dark,
            theme::Appearance::Dark => theme::Appearance::Light,
        };
        let spelled = match away {
            theme::Appearance::Light => "light",
            theme::Appearance::Dark => "dark",
        };
        write_user_theme("mine.json", "Quokka", "dark", "#405060");
        write_user_theme("imported.json", "Imported", spelled, "#eeeeee");
        theme::user::reload();
        let imported = theme::Theme::all()
            .into_iter()
            .find(|theme| theme.name == "Imported")
            .unwrap();
        workspace.update_in(cx, |workspace, window, cx| {
            workspace.set_theme(Some(away), imported, window, cx)
        });
        let worn = poll_themes(cx);

        // Previewed from a list opened before its file changed, every side
        // listed.
        workspace.update(cx, |workspace, _| {
            workspace.settings.match_system_appearance = false
        });
        workspace.update_in(cx, |workspace, window, cx| {
            workspace.select_theme(&crate::actions::SelectTheme, window, cx)
        });
        settle(cx);
        cx.simulate_input("zircon");
        settle(cx);
        write_user_theme("other.json", "Zircon", "dark", "#222222");
        let previewed = poll_themes(cx);
        // The theme behind the list changes too, and leaving puts it back.
        write_user_theme("mine.json", "Quokka", "dark", "#506070");
        poll_themes(cx);
        cx.simulate_keystrokes("escape");
        settle(cx);
        let restored = shown(cx);

        // Confirmed after a reread the list has not yet shown.
        workspace.update_in(cx, |workspace, window, cx| {
            workspace.select_theme(&crate::actions::SelectTheme, window, cx)
        });
        settle(cx);
        cx.simulate_input("zircon");
        settle(cx);
        write_user_theme("other.json", "Zircon", "dark", "#333333");
        theme::user::reload();
        cx.simulate_keystrokes("enter");
        settle(cx);
        let confirmed = shown(cx);
        let kept = poll_themes(cx);
        quit(workspace, cx);

        assert_eq!(worn.name, "Quokka");
        assert_eq!(worn.surface.hex(), "#405060");
        assert_eq!(previewed.name, "Zircon");
        assert_eq!(previewed.surface.hex(), "#222222");
        assert_eq!(restored.name, "Quokka");
        assert_eq!(restored.surface.hex(), "#506070");
        assert_eq!(confirmed.name, "Zircon");
        assert_eq!(confirmed.surface.hex(), "#333333");
        assert_eq!(kept, confirmed);
    });
}

