#[gpui::test]
fn a_failed_save_keeps_the_hide_and_the_kill_switch_for_the_next(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        let (workspace, cx) =
            launch_with_profiles(cx, &sqlite_profile("dev", "Dev", "agent_visible = true"));
        let path = store::dbdelve_directory().unwrap().join("profiles.toml");
        let mut list = store::peek_profiles(&[]).expect("profiles.toml reads back");
        list.settings
            .as_mut()
            .expect("the launch save wrote settings")
            .agent_access = Some(true);
        // A directory where the file goes: every write to it fails.
        std::fs::remove_file(&path).expect("the file is removable");
        std::fs::create_dir(&path).expect("the directory is creatable");

        workspace.update(cx, |workspace, cx| {
            workspace.agent.access_choice = Some(false);
            workspace.set_agent_visible("dev", false, cx);
        });
        workspace.read_with(cx, |workspace, _| {
            assert!(workspace.agent.visibility_choices.contains("dev"));
            assert_eq!(workspace.agent.access_choice, Some(false));
        });

        // The file comes back still granting both; the next save writes the
        // two choices over it rather than taking its grant back on.
        std::fs::remove_dir(&path).expect("the directory is removable");
        store::save_profiles(&list).expect("the file is writable again");
        workspace.update(cx, |workspace, cx| workspace.remember_profiles(cx));
        assert!(!agent_visible(&workspace, cx, "dev"));
        assert!(!saved_visible("dev"));
        let saved = store::peek_profiles(&[]).expect("profiles.toml reads back");
        assert_eq!(saved.settings.and_then(|s| s.agent_access), Some(false));
        workspace.read_with(cx, |workspace, _| {
            assert!(workspace.agent.visibility_choices.is_empty());
            assert_eq!(workspace.agent.access_choice, None);
        });
        quit(workspace, cx);
    });
}

#[gpui::test]
fn a_new_target_hides_a_grant_this_window_had_not_taken_on_yet(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        let (workspace, cx) = launch_with_profiles(cx, &sqlite_profile("dev", "Dev", ""));
        assert!(!agent_visible(&workspace, cx, "dev"));

        // Another window granted it, for the target this one still has.
        let mut list = store::peek_profiles(&[]).expect("profiles.toml reads back");
        list.profiles
            .iter_mut()
            .find(|profile| profile.id == "dev")
            .expect("the profile was saved")
            .agent_visible = true;
        store::save_profiles(&list).expect("the other window saves");

        // A timeout is a change `needs_reconnect` sees and `retargets` does not.
        workspace.update_in(cx, |workspace, window, cx| {
            let mut config = workspace.profiles[0].config.clone();
            if let ConnectionConfig::Sqlite {
                statement_timeout, ..
            } = &mut config
            {
                *statement_timeout += 1;
            }
            workspace.save_profile("dev", "Dev".into(), config, None, window, cx);
        });
        assert!(!agent_visible(&workspace, cx, "dev"));
        assert!(!saved_visible("dev"));
        quit(workspace, cx);
    });
}

#[gpui::test]
fn switching_the_database_hides_the_profile_from_agents(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        // Snowflake, as in `an_unedited_save_keeps_visibility_and_a_new_host_hides`:
        // its connect fails on the missing key before it reaches the network.
        let (workspace, cx) = launch_with_profiles(
            cx,
            "[[profiles]]\nid = \"warehouse\"\nname = \"Warehouse\"\n\
             host = \"dev.example.invalid\"\ndatabase = \"ANALYTICS\"\nuser = \"TIM\"\n\
             engine = \"snowflake\"\naccount = \"myorg-myaccount\"\n\
             private_key = \"/no-such-dir/dbdelve-e2e.p8\"\nagent_visible = true\n",
        );
        workspace.update(cx, |workspace, cx| workspace.activate(0, cx));
        cx.run_until_parked();
        assert!(agent_visible(&workspace, cx, "warehouse"));

        // Asking for the database it is on already changes nothing.
        workspace.update_in(cx, |workspace, window, cx| {
            assert!(workspace.set_database("ANALYTICS".into(), window, cx));
        });
        assert!(agent_visible(&workspace, cx, "warehouse"));

        workspace.update_in(cx, |workspace, window, cx| {
            assert!(workspace.set_database("FINANCE".into(), window, cx));
        });
        assert!(!agent_visible(&workspace, cx, "warehouse"));
        assert!(!saved_visible("warehouse"));
        workspace.read_with(cx, |workspace, _| {
            assert_eq!(
                workspace
                    .profile()
                    .and_then(|profile| profile.session.notice.as_deref()),
                Some("Warehouse is hidden from agents because its database changed.")
            );
        });

        // A grant no save has written yet, so the file has no say in it, is
        // dropped by the switch all the same.
        let path = store::dbdelve_directory().unwrap().join("profiles.toml");
        std::fs::remove_file(&path).expect("the file is removable");
        std::fs::create_dir(&path).expect("the directory is creatable");
        workspace.update(cx, |workspace, cx| {
            workspace.agent_visibility_prompt = Some("warehouse".into());
            workspace.set_agent_visible("warehouse", true, cx);
        });
        assert!(agent_visible(&workspace, cx, "warehouse"));
        workspace.update_in(cx, |workspace, window, cx| {
            assert!(workspace.set_database("ANALYTICS".into(), window, cx));
        });
        assert!(!agent_visible(&workspace, cx, "warehouse"));
        std::fs::remove_dir(&path).expect("the directory is removable");

        // A prompt open for the profile when it is withdrawn goes with it, so
        // answering it cannot grant the new target.
        workspace.update(cx, |workspace, _| {
            workspace.agent_visibility_prompt = Some("warehouse".into());
        });
        workspace.update_in(cx, |workspace, window, cx| {
            assert!(workspace.set_database("FINANCE".into(), window, cx));
        });
        assert_eq!(visibility_prompt(&workspace, cx), None);
        workspace.update(cx, |workspace, cx| workspace.confirm_agent_visibility(cx));
        assert!(!agent_visible(&workspace, cx, "warehouse"));
        quit(workspace, cx);
    });
}

