#[gpui::test]
fn copy_results_formats_work_from_menu_and_palette_and_restore_focus(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        let (workspace, cx) = launch_on_sqlite_holding(
            cx,
            "create table birds (id integer primary key, note text);
             insert into birds values (1, null), (2, ''), (3, 'NULL');",
        );
        cx.executor().allow_parking();
        let sql = "select * from birds order by id";
        cx.simulate_input(sql);
        cx.simulate_keystrokes("secondary-enter");
        settle(cx);

        let read_clipboard = |cx: &mut VisualTestContext| {
            let item = cx.read_from_clipboard().expect("copy writes the clipboard");
            let metadata = item.entries().iter().find_map(|entry| match entry {
                gpui::ClipboardEntry::String(string) => string.metadata.clone(),
                _ => None,
            });
            (item.text().unwrap(), metadata)
        };
        let expected = |format: crate::export::ClipboardFormat, cx: &mut VisualTestContext| {
            workspace.read_with(cx, |workspace, cx| {
                let grid = workspace
                    .profile()
                    .unwrap()
                    .session
                    .active_results()
                    .unwrap()
                    .read(cx)
                    .delegate();
                format.render(Engine::Sqlite, grid.result()).unwrap()
            })
        };
        let open_menu = |cx: &mut VisualTestContext| {
            let bounds = cx
                .debug_bounds("export-results")
                .expect("Export button is drawn");
            cx.simulate_click(bounds.center(), gpui::Modifiers::default());
            settle(cx);
            cx.update(|window, _| {
                assert!(
                    window
                        .context_stack()
                        .iter()
                        .any(|context| context.contains("PopupMenu"))
                )
            });
        };

        for object_tab in [false, true] {
            if object_tab {
                let row = explorer_row(&workspace, "relation-main\0birds", cx).center();
                cx.simulate_click(row, gpui::Modifiers::default());
                settle(cx);
            }
            open_menu(cx);
            cx.simulate_keystrokes("down");
            press(cx, "enter");
            assert_eq!(
                read_clipboard(cx).0,
                expected(crate::export::ClipboardFormat::Tsv, cx)
            );

            for (ix, format) in crate::export::ClipboardFormat::ALL.into_iter().enumerate() {
                cx.write_to_clipboard(gpui::ClipboardItem::new_string("before menu".into()));
                open_menu(cx);
                cx.simulate_keystrokes("down down");
                settle(cx);
                // The menu hangs off the right edge, so its submenu opens leftwards.
                cx.simulate_keystrokes("left");
                settle(cx);
                for _ in 0..ix {
                    cx.simulate_keystrokes("down");
                }
                press(cx, "enter");
                let (text, metadata) = read_clipboard(cx);
                assert_eq!(text, expected(format, cx), "menu {format:?}");
                let metadata = metadata.expect("all successful table copies carry original rows");
                let metadata: serde_json::Value = serde_json::from_str(&metadata).unwrap();
                assert_eq!(metadata["rows"][0]["note"], serde_json::Value::Null);
                assert_eq!(metadata["rows"][1]["note"], "");
                assert_eq!(metadata["rows"][2]["note"], "NULL");
                assert!(metadata["columns"][0]["type"].is_string());
                let (_, bytes, _) = crate::import_rows::pasted(
                    &text,
                    Some(&serde_json::to_string(&metadata).unwrap()),
                    false,
                )
                .unwrap();
                let pasted: Vec<serde_json::Value> = String::from_utf8(bytes)
                    .unwrap()
                    .lines()
                    .map(|line| serde_json::from_str(line).unwrap())
                    .collect();
                assert_eq!(pasted, metadata["rows"].as_array().unwrap().clone());
                settle(cx);
                cx.update(|window, _| {
                    assert!(
                        !window
                            .context_stack()
                            .iter()
                            .any(|context| context.contains("PopupMenu"))
                    )
                });

                cx.write_to_clipboard(gpui::ClipboardItem::new_string("before palette".into()));
                cx.simulate_keystrokes("secondary-shift-p");
                settle(cx);
                cx.simulate_input(&format!("Copy results as {}", format.label()));
                press(cx, "enter");
                assert_eq!(read_clipboard(cx).0, text, "palette {format:?}");
            }
            open_menu(cx);
            press(cx, "escape");
            cx.update(|window, cx| {
                assert!(
                    !window
                        .context_stack()
                        .iter()
                        .any(|context| context.contains("PopupMenu"))
                );
                assert!(
                    window.focused(cx).is_some(),
                    "Escape returns a live dispatch path"
                );
            });
            // The existing copy action still defaults to TSV after a table format
            // was used. Copy Results has no default chord, so it is dispatched
            // once the chord has moved the keyboard to the results; a sentinel
            // first, so a copy that did nothing cannot pass on an earlier one.
            cx.write_to_clipboard(gpui::ClipboardItem::new_string("before copy".into()));
            cx.simulate_keystrokes("secondary-k r");
            settle(cx);
            cx.update(|window, cx| {
                window.dispatch_action(Box::new(crate::actions::CopyResults), cx);
            });
            assert_eq!(
                read_clipboard(cx).0,
                expected(crate::export::ClipboardFormat::Tsv, cx)
            );
            if !object_tab {
                assert_eq!(buffer(&workspace, cx), sql);
            } else {
                let grid = workspace.read_with(cx, |workspace, _| {
                    workspace
                        .profile()
                        .unwrap()
                        .session
                        .active_results()
                        .unwrap()
                        .clone()
                });
                grid.update(cx, |grid, cx| {
                    assert!(grid.delegate_mut().set_pending(
                        0,
                        1,
                        crate::result_grid::NewValue::Value("pending".into())
                    ));
                    cx.notify();
                });
                workspace.update(cx, |_, cx| cx.notify());
                settle(cx);
                assert!(cx.debug_bounds("export-results").is_none());
                for format in crate::export::ClipboardFormat::ALL {
                    workspace.update(cx, |workspace, cx| workspace.copy_results_as(format, cx));
                    assert_eq!(read_clipboard(cx).0, expected(format, cx));
                    assert!(!read_clipboard(cx).0.contains("pending"));
                }
                grid.update(cx, |grid, _| grid.delegate_mut().discard_pending());
            }
        }
        quit(workspace, cx);
    });
}

#[gpui::test]
fn refused_table_copies_preserve_the_clipboard(cx: &mut TestAppContext) {
    store::tests::with_home(|| {
        let (workspace, cx) = launch_on_sqlite(cx);
        let grid = workspace.read_with(cx, |workspace, _| {
            workspace
                .profile()
                .unwrap()
                .session
                .active_results()
                .unwrap()
                .clone()
        });
        let column = crate::db::Column {
            name: "v".into(),
            data_type: Some("text".into()),
        };
        let result = crate::db::QueryResult {
            columns: vec![column.clone()],
            rows: crate::db::rows(vec![vec![Some(
                "x".repeat(crate::result_grid::COPIED_ROWS_TEXT_LIMIT),
            )]]),
            ..Default::default()
        };
        grid.update(cx, |grid, _| {
            *grid.delegate_mut() =
                crate::result_grid::ResultGrid::new(result, crate::sql::Mode::ReadOnly);
        });
        cx.write_to_clipboard(gpui::ClipboardItem::new_string("previous clipboard".into()));
        for format in crate::export::ClipboardFormat::ALL.into_iter().skip(2) {
            workspace.update(cx, |workspace, cx| workspace.copy_results_as(format, cx));
            assert_eq!(
                cx.read_from_clipboard().unwrap().text().as_deref(),
                Some("previous clipboard")
            );
            workspace.read_with(cx, |workspace, _| {
                assert_eq!(
                    workspace.profile().unwrap().session.notice.as_deref(),
                    Some("Table output exceeds 16 MiB. Copy as TSV/CSV or export to a file.")
                );
            });
        }
        let width = (crate::result_grid::COPIED_ROWS_TEXT_LIMIT - 24) / 5;
        let value = format!("{}\u{301}", "x".repeat(width));
        grid.update(cx, |grid, _| {
            *grid.delegate_mut() = crate::result_grid::ResultGrid::new(
                crate::db::QueryResult {
                    columns: vec![column.clone()],
                    rows: crate::db::rows(vec![vec![Some(value.clone())]]),
                    ..Default::default()
                },
                crate::sql::Mode::ReadOnly,
            );
        });
        workspace.update(cx, |workspace, cx| {
            workspace.copy_results_as(crate::export::ClipboardFormat::AsciiTable, cx);
        });
        let item = cx.read_from_clipboard().unwrap();
        assert_eq!(
            item.text().unwrap().len(),
            crate::result_grid::COPIED_ROWS_TEXT_LIMIT
        );
        let metadata = item
            .entries()
            .iter()
            .find_map(|entry| match entry {
                gpui::ClipboardEntry::String(string) => string.metadata.as_deref(),
                _ => None,
            })
            .unwrap();
        let metadata: serde_json::Value = serde_json::from_str(metadata).unwrap();
        assert_eq!(metadata["rows"][0]["v"], value);
        cx.write_to_clipboard(gpui::ClipboardItem::new_string("previous clipboard".into()));
        for result in [
            crate::result_grid::ResultGrid::new(
                crate::db::QueryResult::default(),
                crate::sql::Mode::ReadOnly,
            ),
            crate::result_grid::ResultGrid::new(
                crate::db::QueryResult {
                    columns: vec![column.clone()],
                    capped_from: Some(10),
                    ..Default::default()
                },
                crate::sql::Mode::ReadOnly,
            ),
            crate::result_grid::ResultGrid::new(
                crate::db::QueryResult {
                    columns: vec![column],
                    ..Default::default()
                },
                crate::sql::Mode::ReadOnly,
            )
            .streaming(0),
        ] {
            grid.update(cx, |grid, _| *grid.delegate_mut() = result);
            for format in crate::export::ClipboardFormat::ALL {
                workspace.update(cx, |workspace, cx| workspace.copy_results_as(format, cx));
                assert_eq!(
                    cx.read_from_clipboard().unwrap().text().as_deref(),
                    Some("previous clipboard")
                );
            }
        }
        quit(workspace, cx);
    });
}

/// One `[[profiles]]` table of a ClickHouse profile `Clicks` (id `clicks`) on
/// a mock's `port`, as `profiles.toml` spells one.
fn clickhouse_profile(port: u16) -> String {
    format!(
        "[[profiles]]\nid = \"clicks\"\nname = \"Clicks\"\nhost = \"127.0.0.1\"\nport = {port}\n\
         database = \"dbdelve_dev\"\nuser = \"me@example.com\"\nengine = \"clickhouse\"\n\
         sslmode = \"disable\"\n"
    )
}

/// The columns a ClickHouse mock answers a relations read with.
const RELATION_COLUMNS: [(&str, &str); 5] = [
    ("schema_name", "String"),
    ("relation_name", "String"),
    ("relation_kind", "String"),
    ("size_bytes", "Nullable(UInt64)"),
    ("row_estimate", "Nullable(UInt64)"),
];

/// Answer a ClickHouse mock the way a server holding `analytics` and
/// `dbdelve_dev` does: one table in each, and those two as the databases the
/// tree draws. A read that names `dbdelve_dev` alone gets that one's table
/// only, as a server answering the `IN` list a filter writes does.
fn route_clickhouse_catalog(mock: &crate::db::clickhouse_mock::Mock) {
    use crate::db::clickhouse_mock::Response;

    let relations = RELATION_COLUMNS;
    let listing = [("name", "String"), ("is_current", "UInt8")];
    mock.on_statement(
        "relation_kind",
        [Response::rows(
            &relations,
            &[
                &["analytics", "events", "table", "\\N", "\\N"],
                &["dbdelve_dev", "orders", "table", "\\N", "\\N"],
            ],
        )],
    );
    mock.on_statement(
        "database IN ('dbdelve_dev')",
        [Response::rows(
            &relations,
            &[&["dbdelve_dev", "orders", "table", "\\N", "\\N"]],
        )],
    );
    for statement in ["SELECT DISTINCT database", "FROM system.databases"] {
        mock.on_statement(
            statement,
            [Response::rows(
                &listing,
                &[&["analytics", "0"], &["dbdelve_dev", "1"]],
            )],
        );
    }
}

/// The app launched with an SQLite profile in front and a ClickHouse profile
/// `clicks` idle beside it, on a mock server that answers its catalog.
///
/// The SQLite one is first because the launch connects only the profile it
/// puts in front, and the ClickHouse one must not be connected before
/// [`connect_clicks`] has filled its password slot.
fn launch_beside_a_clickhouse_mock(
    cx: &mut TestAppContext,
) -> (
    crate::db::clickhouse_mock::Mock,
    Entity<Workspace>,
    &mut VisualTestContext,
) {
    crate::IGNORE_ENVIRONMENT.set(true);
    let mock = crate::db::clickhouse_mock::Mock::start();
    // Opened and dropped at once: what it leaves on the mock is the routes of
    // the open handshake, which the app's own open then finds.
    drop(mock.connection());
    route_clickhouse_catalog(&mock);
    let port = mock.server().port.expect("the mock listens on a port");
    let (workspace, cx) = launch_connections(
        cx,
        "",
        "",
        &[
            sqlite_profile("orders", "Orders", ""),
            clickhouse_profile(port),
        ]
        .concat(),
    );
    (mock, workspace, cx)
}

fn clicks_connection_is_open(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) -> bool {
    workspace.read_with(cx, |workspace, _| {
        workspace
            .profiles
            .iter()
            .find(|profile| profile.id == "clicks")
            .is_some_and(|profile| profile.connection().is_some())
    })
}

/// Bring `clicks` to the front and wait until its connection is open.
fn connect_clicks(workspace: &Entity<Workspace>, cx: &mut VisualTestContext) {
    workspace.update(cx, |workspace, _| {
        let profile = workspace
            .profiles
            .iter_mut()
            .find(|profile| profile.id == "clicks")
            .expect("the profile was restored");
        // A password slot that holds something is never looked up in the OS
        // keychain, which a headless Linux CI may not have and a test must not
        // touch.
        *profile
            .config
            .password_mut()
            .expect("a server profile has a password slot") = "unused".to_string();
    });
    activate_by_id(workspace, cx, "clicks");
    drive_until(cx, |cx| clicks_connection_is_open(workspace, cx));
    settle(cx);
}

/// The generation and config of the profile `clicks`, which only a
/// reconnect or an edit of the connection moves.
fn clicks_connection(
    workspace: &Entity<Workspace>,
    cx: &mut VisualTestContext,
) -> (u64, crate::db::ConnectionConfig) {
    workspace.read_with(cx, |workspace, _| {
        let profile = workspace
            .profiles
            .iter()
            .find(|profile| profile.id == "clicks")
            .expect("the profile was restored");
        (profile.generation, profile.config.clone())
    })
}

/// `clicks` connected in front, its filter picker open on it with `nomatch*`
/// typed into the database patterns and its databases listed.
fn clicks_with_a_pattern_typed(
    cx: &mut TestAppContext,
) -> (
    crate::db::clickhouse_mock::Mock,
    Entity<Workspace>,
    &mut VisualTestContext,
) {
    use super::filter_picker::Listing;

    let (mock, workspace, cx) = launch_beside_a_clickhouse_mock(cx);
    cx.executor().allow_parking();
    connect_clicks(&workspace, cx);
    workspace.update_in(cx, |workspace, window, cx| {
        workspace.open_filter_picker("clicks", window, cx);
    });
    drive_until(cx, |cx| {
        workspace.read_with(cx, |workspace, _| {
            workspace
                .filter_picker
                .as_ref()
                .is_some_and(|picker| matches!(picker.databases.listing, Listing::Loaded(_)))
        })
    });
    settle(cx);
    click_selector(cx, "filter-picker-patterns-databases");
    cx.simulate_input("nomatch*");
    settle(cx);
    (mock, workspace, cx)
}

/// Start the first catalog read of `clicks` as a connect leaves it, and save
/// the picker's filter in the same update.
///
/// No response is held: `spawn_blocking` runs each read inline on this thread
/// inside `run_until_parked`, so a held one could never be released. The read
/// is under way because it was started here and the scheduler has not run
/// since, which the assert at the save shows.
fn save_the_filter_during_the_first_read(
    workspace: &Entity<Workspace>,
    cx: &mut VisualTestContext,
    during: impl FnOnce(&mut Workspace, &mut gpui::Window, &mut gpui::Context<Workspace>),
) {
    let (generation, _) = clicks_connection(workspace, cx);
    workspace.update_in(cx, |workspace, window, cx| {
        let profile = workspace.profile_mut().expect("clicks is in front");
        profile.catalog = CatalogState::Loading;
        workspace.load_catalog("clicks", generation, cx);
        workspace.save_filter(cx);
        let profile = workspace.profile().expect("clicks is in front");
        assert_eq!(profile.include.databases, ["nomatch*"]);
        assert!(profile.reread_after_load, "it waits for the read under way");
        during(workspace, window, cx);
    });
}

#[gpui::test]
fn a_filter_saved_while_the_first_catalog_read_runs_is_not_left_waiting_when_that_read_fails(
    cx: &mut TestAppContext,
) {
    use crate::db::clickhouse_mock::Response;

    store::tests::with_home(|| {
        let (mock, workspace, cx) = clicks_with_a_pattern_typed(cx);
        mock.on_statement(
            "relation_kind",
            [
                Response::error(500, 241, "MEMORY_LIMIT_EXCEEDED", "Memory limit exceeded"),
                Response::rows(
                    &RELATION_COLUMNS,
                    &[&["dbdelve_dev", "orders", "table", "\\N", "\\N"]],
                ),
            ],
        );
        save_the_filter_during_the_first_read(&workspace, cx, |_, _, _| {});
        settle(cx);
        workspace.read_with(cx, |workspace, _| {
            let profile = workspace.profile().expect("clicks is in front");
            assert!(
                matches!(profile.catalog, CatalogState::Failed(_)),
                "the first read failed"
            );
            assert!(
                !profile.reread_after_load,
                "a read that stored no catalog left the save waiting"
            );
        });

        let before = mock.hits("relation_kind");
        workspace.update(cx, |workspace, cx| workspace.refresh_schema(cx));
        drive_until(cx, |cx| {
            workspace.read_with(cx, |workspace, _| {
                let profile = workspace.profile().expect("clicks is in front");
                matches!(profile.catalog, CatalogState::Loaded(..)) && !profile.refreshing_schema()
            })
        });
        settle(cx);
        assert_eq!(
            mock.hits("relation_kind"),
            before + 1,
            "the Refresh read once and nothing followed it"
        );
        workspace.read_with(cx, |workspace, _| {
            assert!(
                !workspace
                    .profile()
                    .expect("clicks is in front")
                    .reread_after_load
            );
        });
        assert_eq!(own_catalog(&workspace, cx).0, ["dbdelve_dev"]);
        quit(workspace, cx);
    });
}

#[gpui::test]
fn a_connect_that_fails_leaves_no_saved_filter_waiting(cx: &mut TestAppContext) {
    use crate::db::clickhouse_mock::Response;

    store::tests::with_home(|| {
        let (mock, workspace, cx) = clicks_with_a_pattern_typed(cx);
        mock.on_statement(
            "system.settings",
            [Response::error(
                500,
                497,
                "ACCESS_DENIED",
                "Not enough privileges",
            )],
        );
        // The reconnect bumps the generation, so the read started a moment
        // before belongs to the old one and its landing is dropped.
        save_the_filter_during_the_first_read(&workspace, cx, |workspace, window, cx| {
            workspace.run_command(Command::Reconnect, window, cx);
        });
        drive_until(cx, |cx| {
            workspace.read_with(cx, |workspace, _| {
                let profile = workspace.profile().expect("clicks is in front");
                profile.connection().is_none() && matches!(profile.catalog, CatalogState::Failed(_))
            })
        });
        settle(cx);
        workspace.read_with(cx, |workspace, _| {
            let profile = workspace.profile().expect("clicks is in front");
            assert!(
                !profile.reread_after_load,
                "a connect that failed left the save waiting"
            );
        });
        quit(workspace, cx);
    });
}

