        workspace.update(cx, |workspace, _| {
            let tab = workspace
                .profile_mut()
                .unwrap()
                .session
                .objects
                .iter_mut()
                .find(|tab| tab.id == id)
                .unwrap();
            let ObjectBody::Relation { stale, .. } = &mut tab.body else {
                panic!("a relation tab");
            };
            *stale = true;
        });

